_merge":{"bank_review_release":"20261114-bank-review","bank_review_date":"2026-11-14","replacement_question_id":"1840ed87-8e41-51f1-8ded-51622e9abc33","replacement_review_release":"20261114-bank-review","replacement_review_note":"Explicitly specify degrees; the original omitted the angle unit."},"assets_remove":[],"reasons":["Retain the defective source and link its independently checked adaptation."]},{"id":"fddc7217-091d-5eb2-9649-52643c66cac0","row_hash":"3ec641e52ff5628248d2e3f7ba3c2da1","key_hash":"bbb71caa41425235eb3621773d6be5dd","fields":{},"assets_merge":{"bank_review_release":"20261114-bank-review","bank_review_date":"2026-11-14","replacement_question_id":"4a6bf68a-0db8-57eb-a159-7142ddc2aac7","replacement_review_release":"20261114-bank-review","replacement_review_note":"Add the necessary regularity condition omitted by the source."},"assets_remove":[],"reasons":["Retain the defective source and link its independently checked adaptation."]},{"id":"b6763c00-7ba0-5573-a0ce-4434dd00d24c","row_hash":"6cd22eff5cef5d653e83e5b28883db39","key_hash":"4b46cecee0bf07da067113f641f7cdf5","fields":{},"assets_merge":{"bank_review_release":"20261114-bank-review","bank_review_date":"2026-11-14","replacement_question_id":"771caf47-a5b8-508f-8b51-b6a4cf225aa8","replacement_review_release":"20261114-bank-review","replacement_review_note":"Replace 600/1000 with the explicitly instructor-authored 2/5 option. Both defective copies link to this single adaptation."},"assets_remove":[],"reasons":["Retain the defective source and link its independently checked adaptation."]},{"id":"c0edf793-69ae-51f1-9c63-00444e743f84","row_hash":"a8d3d6c71ef83ae5cdc894909fc1ad8a","key_hash":"9ce1401adb5427b24fc513513914f5b4","fields":{},"assets_merge":{"bank_review_release":"20261114-bank-review","bank_review_date":"2026-11-14","replacement_question_id":"771caf47-a5b8-508f-8b51-b6a4cf225aa8","replacement_review_release":"20261114-bank-review","replacement_review_note":"Replace 600/1000 with the explicitly instructor-authored 2/5 option. Both defective copies link to this single adaptation."},"assets_remove":[],"reasons":["Retain the defective source and link its independently checked adaptation."]}],"additions":[{"id":"8939b729-8bd1-51df-8977-55604d2a2685","track_id":"act2","topic":"Trigonometry","difficulty":"medium","type":"grid_in","stem":"A 20-meter ladder rests against a vertical wall on level ground. The ladder makes an angle of 65° with the ground. How high up the wall does it reach, in meters? Round to the nearest hundredth.","choices":[],"correct":"18.13","explanation":"The ladder is the hypotenuse. Its vertical height is 20 sin 65° ≈ 18.12616 meters, which rounds to 18.13 meters.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["1115c92c-eca5-5c40-b42f-f782066e4eff"],"content_origin":"instructor_adaptation","adaptation_reason":"Add explicit nearest-hundredth precision and the right-triangle setting.","curriculum_lesson":"Trigonometry","lesson_subtopic":"Trigonometry","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"408891c1-3d35-5197-8b59-dc5a2976bce0","track_id":"act2","topic":"Logarithms and exponentials","difficulty":"medium","type":"mcq","stem":"For real x, solve $\\log_3(x-1)+\\log_3(x+1)=2$.","choices":[{"key":"A","text":"$-\\sqrt{10}$"},{"key":"B","text":"$\\sqrt{10}$"},{"key":"C","text":"10"},{"key":"D","text":"3"}],"correct":"B","explanation":"The domain requires x > 1. Combining logarithms gives $\\log_3(x^2-1)=2$, so x² − 1 = 9 and x = ±√10. Only √10 satisfies the domain.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["2da9d842-d0a0-5b81-a3e7-831e75a4f515"],"content_origin":"instructor_adaptation","adaptation_reason":"Provide instructor-authored exact-answer choices so no unstated rounding is required.","curriculum_lesson":"Logarithms and exponentials","lesson_subtopic":"Logarithms and exponentials","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"cb2bb778-72a0-5a82-9020-f02afd4a2f9f","track_id":"act2","topic":"Trigonometry","difficulty":"medium","type":"mcq","stem":"In triangle ABC, sides a = 7 and b = 10 are opposite angles A and B. The included angle C is 60°. What is the exact length of side c, opposite C?","choices":[{"key":"A","text":"$\\sqrt{79}$"},{"key":"B","text":"$\\sqrt{149}$"},{"key":"C","text":"17"},{"key":"D","text":"3"}],"correct":"A","explanation":"By the cosine rule, c² = 7² + 10² − 2(7)(10) cos 60° = 149 − 70 = 79. Since c is a length, c = √79.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["98cb24bf-e675-5d2e-a4c0-bd834cbbc0f2"],"content_origin":"instructor_adaptation","adaptation_reason":"State the side convention and add exact-answer choices.","curriculum_lesson":"Trigonometry","lesson_subtopic":"Trigonometry","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"3cae9561-7bf7-525b-98ac-d5bcdaf42b5f","track_id":"act2","topic":"Circles","difficulty":"easy","type":"mcq","stem":"A circle has a diameter of 11 inches. What is its exact circumference?","choices":[{"key":"A","text":"$11\\pi$ inches"},{"key":"B","text":"$22\\pi$ inches"},{"key":"C","text":"$121\\pi$ inches"},{"key":"D","text":"$\\frac{11\\pi}{2}$ inches"}],"correct":"A","explanation":"Circumference is π times diameter, so C = 11π inches.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["a66e7923-397b-5cd5-995c-04205246199d"],"content_origin":"instructor_adaptation","adaptation_reason":"Supply exact-answer choices for an unsupported irrational numeric response.","curriculum_lesson":"Circles","lesson_subtopic":"Circles","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"b5a5f8a4-5298-5c01-bbc0-4459b3f92ac4","track_id":"act2","topic":"Circles","difficulty":"easy","type":"mcq","stem":"A circle has a diameter of 17 units. What is its exact area?","choices":[{"key":"A","text":"$17\\pi$"},{"key":"B","text":"$\\frac{289\\pi}{4}$"},{"key":"C","text":"$289\\pi$"},{"key":"D","text":"$\\frac{17\\pi}{2}$"}],"correct":"B","explanation":"The radius is 17/2. Area = π(17/2)² = 289π/4 square units.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["d0ffb261-513f-551b-88c4-9b6845e98178"],"content_origin":"instructor_adaptation","adaptation_reason":"Supply exact-answer choices instead of assuming an unstated decimal precision.","curriculum_lesson":"Circles","lesson_subtopic":"Circles","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"675a3178-810f-5531-8d6b-6497f8e7783d","track_id":"act2","topic":"Quadratics and polynomials","difficulty":"medium","type":"mcq","stem":"Which is the positive solution of 6x² − 7x − 3 = 0?","choices":[{"key":"A","text":"−1/3"},{"key":"B","text":"3/2"},{"key":"C","text":"−3/2"},{"key":"D","text":"1/3"}],"correct":"B","explanation":"Factor as (3x + 1)(2x − 3) = 0. The roots are −1/3 and 3/2; only 3/2 is positive.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["9b4f5a2d-27d7-5210-922a-31e2556e7130"],"content_origin":"instructor_adaptation","adaptation_reason":"Add “positive” to remove the source’s two-correct-choice ambiguity.","curriculum_lesson":"Quadratics and polynomials","lesson_subtopic":"Quadratics and polynomials","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"0828b97c-3414-534e-8ed4-db26d79079a8","track_id":"act2","topic":"Statistics and data analysis","difficulty":"medium","type":"mcq","stem":"Ted’s first five scores were 70, 70, 80, 70, and 80. Two more scores, 90 and 95, are added to the same data set. How do the mean and median change?","choices":[{"key":"A","text":"Mean increases by 5; median stays the same"},{"key":"B","text":"Mean increases by 37/7; median increases by 10"},{"key":"C","text":"Mean increases by 10; median increases by 37/7"},{"key":"D","text":"Mean increases by 37/7; median stays the same"}],"correct":"B","explanation":"The original sum is 370, so the mean is 74 and median 70. The new sum is 555, so the mean is 555/7 and its increase is 555/7 − 74 = 37/7. The sorted seven scores have median 80, an increase of 10.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["9b45a010-891a-5c72-aeb0-4346e6f82c3f"],"content_origin":"instructor_adaptation","adaptation_reason":"Replace defective options with instructor-authored choices, including the exact changes.","curriculum_lesson":"Statistics and data analysis","lesson_subtopic":"Statistics and data analysis","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"c7f7ee46-421c-5022-ba22-5c9ae0c1b5b6","track_id":"act2","topic":"Statistics and data analysis","difficulty":"medium","type":"mcq","stem":"The data set is 75, 70, 80, 70, 80, 90, 95, 70, 70, 75, 80, 80, 90, 95. Which statement correctly compares its mean and median?","choices":[{"key":"A","text":"The mean is less than the median"},{"key":"B","text":"The mean equals the median"},{"key":"C","text":"The mean is greater than the median"},{"key":"D","text":"The mean and median cannot be determined"}],"correct":"B","explanation":"The sum is 1120 and there are 14 values, so the mean is 80. The seventh and eighth sorted values are both 80, so the median is also 80.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["93b5da55-a8b7-58f0-a38c-4e4fc3d1fcb1"],"content_origin":"instructor_adaptation","adaptation_reason":"Convert the unsupported descriptive response to a single multiple-choice comparison.","curriculum_lesson":"Statistics and data analysis","lesson_subtopic":"Statistics and data analysis","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"4236b337-2e07-522f-aee7-58ea04c01fd7","track_id":"act2","topic":"Circles","difficulty":"medium","type":"grid_in","stem":"A car tire of radius 14 inches rolls without slipping for 1 mile. How many rotations does it make, rounded to the nearest whole number? Use 1 mile = 5,280 feet.","choices":[],"correct":"720","explanation":"One mile is 5,280 × 12 = 63,360 inches. One rotation covers 2π(14) = 28π inches. Thus the number of rotations is 63,360/(28π) ≈ 720.288, which rounds to 720.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["a7e0c938-c48b-50d8-88b3-8388c07f0560"],"content_origin":"instructor_adaptation","adaptation_reason":"Add explicit whole-number rounding; do not silently substitute π = 22/7.","curriculum_lesson":"Circles","lesson_subtopic":"Circles","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"1840ed87-8e41-51f1-8ded-51622e9abc33","track_id":"act2","topic":"Complex numbers","difficulty":"medium","type":"mcq","stem":"Write z = 4(cos 60° + i sin 60°) in rectangular form.","choices":[{"key":"A","text":"$2+2\\sqrt3\\,i$"},{"key":"B","text":"$2\\sqrt3+2i$"},{"key":"C","text":"$4+i$"},{"key":"D","text":"$2-2\\sqrt3\\,i$"}],"correct":"A","explanation":"Using cos 60° = 1/2 and sin 60° = √3/2 gives z = 2 + 2√3 i.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["e79575f2-6d3f-55d4-a583-f6b42f9f949e"],"content_origin":"instructor_adaptation","adaptation_reason":"Explicitly specify degrees; the original omitted the angle unit.","curriculum_lesson":"Complex numbers","lesson_subtopic":"Complex numbers","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"4a6bf68a-0db8-57eb-a159-7142ddc2aac7","track_id":"act2","topic":"Angles and polygons","difficulty":"easy","type":"mcq","stem":"What is the measure, in degrees, of each interior angle of a regular octagon?","choices":[{"key":"A","text":"135"},{"key":"B","text":"180"},{"key":"C","text":"160"},{"key":"D","text":"45"}],"correct":"A","explanation":"The interior-angle sum is (8 − 2) × 180° = 1080°. In a regular octagon all eight angles are equal, so each is 1080°/8 = 135°.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["fddc7217-091d-5eb2-9649-52643c66cac0"],"content_origin":"instructor_adaptation","adaptation_reason":"Add the necessary regularity condition omitted by the source.","curriculum_lesson":"Angles and polygons","lesson_subtopic":"Angles and polygons","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}},{"id":"771caf47-a5b8-508f-8b51-b6a4cf225aa8","track_id":"act2","topic":"Ratios, percentages and unit conversion","difficulty":"easy","type":"mcq","stem":"All of the following numbers are greater than 1/2 EXCEPT:","choices":[{"key":"A","text":"$\\frac{101}{200}$"},{"key":"B","text":"$\\frac{17}{33}$"},{"key":"C","text":"$\\frac7{12}$"},{"key":"D","text":"$\\frac25$"}],"correct":"D","explanation":"101/200 > 1/2 because 202 > 200; 17/33 > 1/2 because 34 > 33; 7/12 > 1/2 because 14 > 12. But 2/5 = 0.4 < 1/2. Thus only D is an exception.","assets":{"source":"Ghoneem Math — reviewed instructor adaptation","source_ids_adapted":["b6763c00-7ba0-5573-a0ce-4434dd00d24c","c0edf793-69ae-51f1-9c63-00444e743f84"],"content_origin":"instructor_adaptation","adaptation_reason":"Replace 600/1000 with the explicitly instructor-authored 2/5 option. Both defective copies link to this single adaptation.","curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Ratios, percentages and unit conversion","verified_release":"20261114-bank-review","answer_review_status":"independently_solved","figure_required":false,"bank_review_date":"2026-11-14"}}]}'::jsonb;
 p jsonb; before_q jsonb; before_k jsonb; h text; t text; old_history jsonb := '{}';
 protected_tables text[] := array['attempts','attempt_answers','attempt_results','exams','assignments','revision_sessions','practice_bundle_items','practice_notebook'];
 updated_count int := 0; added_count int := 0;
begin
 -- Lock only the affected question/key rows, in a stable order, before checking hashes.
 perform 1 from questions where id in (select (v->>'id')::uuid from jsonb_array_elements(data_->'updates') v) order by id for update;
 perform 1 from question_keys where question_id in (select (v->>'id')::uuid from jsonb_array_elements(data_->'updates') v) order by question_id for update;
 for p in select value from jsonb_array_elements(data_->'updates') loop
   select to_jsonb(x) into before_q from questions x where id=(p->>'id')::uuid;
   select to_jsonb(x) into before_k from question_keys x where question_id=(p->>'id')::uuid;
   if before_q is null or before_k is null or md5(before_q::text) is distinct from p->>'row_hash' or md5(before_k::text) is distinct from p->>'key_hash'
   then raise exception 'Concurrent content change: %',p->>'id'; end if;
 end loop;
 for p in select value from jsonb_array_elements(data_->'additions') loop
   if exists(select 1 from questions where id=(p->>'id')::uuid) then raise exception 'Adaptation already exists: %',p->>'id'; end if;
   if exists(select 1 from questions x where x.assets->'source_ids_adapted' ?| array(select jsonb_array_elements_text(p->'assets'->'source_ids_adapted')))
   then raise exception 'Source already has an adaptation: %',p->>'id'; end if;
 end loop;
 -- The three clarified statements had no submitted answers at review time.
 if exists(select 1 from attempt_answers where question_id=any(array['38b3ea7c-1a64-5d12-8944-dedd2448b7c9','2574795c-0842-5799-a7a6-9f318be55de6','df2132af-840a-501e-9268-3a64a7d75791']::uuid[]))
 then raise exception 'New answers require separate versioning before clarification'; end if;
 if exists(select 1 from attempts a join exams e on e.id=a.exam_id where a.status='in_progress' and e.question_ids && array['38b3ea7c-1a64-5d12-8944-dedd2448b7c9','2574795c-0842-5799-a7a6-9f318be55de6','df2132af-840a-501e-9268-3a64a7d75791']::uuid[])
 then raise exception 'Active exam requires separate versioning before clarification'; end if;
 foreach t in array protected_tables loop
   execute format('select md5(coalesce(string_agg(h, %L order by h),%L)) from (select md5(to_jsonb(x)::text) h from public.%I x) s','','',t) into h;
   old_history := old_history || jsonb_build_object(t,h);
 end loop;
 for p in select value from jsonb_array_elements(data_->'updates') loop
   update questions set
    stem=case when p->'fields' ? 'stem' then p->'fields'->>'stem' else stem end,
    choices=case when p->'fields' ? 'choices' then p->'fields'->'choices' else choices end,
    assets=(assets - array(select jsonb_array_elements_text(p->'assets_remove'))) || (p->'assets_merge')
   where id=(p->>'id')::uuid;
   if p->'fields' ? 'explanation' then
    update question_keys set explanation=p->'fields'->>'explanation' where question_id=(p->>'id')::uuid;
   end if;
   updated_count:=updated_count+1;
 end loop;
 for p in select value from jsonb_array_elements(data_->'additions') loop
   insert into questions(id,track_id,topic,difficulty,type,stem,choices,assets)
    values((p->>'id')::uuid,p->>'track_id',p->>'topic',p->>'difficulty',p->>'type',p->>'stem',p->'choices',p->'assets');
   insert into question_keys(question_id,correct,explanation) values((p->>'id')::uuid,p->'correct',p->>'explanation');
   added_count:=added_count+1;
 end loop;
 if updated_count<>65 or added_count<>12 then raise exception 'Unexpected release size'; end if;
 if exists(select 1 from questions q left join question_keys k on k.question_id=q.id
   where q.assets->>'verified_release'=data_->>'release' and not portal_private.question_eligible(q,k,q.track_id,false))
 then raise exception 'Release contains ineligible content'; end if;
 if (select count(*) from questions where assets->>'verified_release'=data_->>'release')<>56 then raise exception 'Unexpected verified release count'; end if;
 foreach t in array protected_tables loop
   execute format('select md5(coalesce(string_agg(h, %L order by h),%L)) from (select md5(to_jsonb(x)::text) h from public.%I x) s','','',t) into h;
   if h is distinct from old_history->>t then raise exception 'Protected assessment history changed: %',t; end if;
 end loop;
end $release$;
commit;
